?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Orders — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Client Portal › Orders</div><div class="portal-welcome"><div><span class="eyebrow mint">ORDERS</span><h1>My Orders</h1><p>Review your WDH purchases and order status.</p></div></div><div class="admin-table"><?php if(!$rows):?><div class="empty">No orders yet.</div><?php else:foreach($rows as $r):?><div class="admin-row"><div><strong><?=e($r['order_number'])?></strong><small><?=e($r['created_at'])?> · Invoice <?=e($r['invoice_number']??'Not generated')?></small></div><span><?=money($r['total'],$r['currency'])?></span><strong><?=e(ucfirst($r['status']))?></strong><a class="btn secondary small" href="order-details.php?order=<?=urlencode($r['order_number'])?>">View</a></div><?php endforeach;endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
